// Strict address shape: 1-2 letters, 1-3 digits, row >= 1.
const ADDRESS_RE = /^[A-Za-z]{1,2}[0-9]{1,3}$/

export function isAddressShape(word) {
  return ADDRESS_RE.test(word)
}

export function colToNum(letters) {
  const up = letters.toUpperCase()
  let n = 0
  for (const ch of up) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

// Parses a word into {col, row} if it is a valid, addressable cell
// reference (1-2 letters, 1-3 digit row >= 1). Returns null otherwise.
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const letterMatch = /^[A-Za-z]{1,2}/.exec(word)
  const digitMatch = /[0-9]{1,3}$/.exec(word)
  const letters = letterMatch[0]
  const digits = digitMatch[0]
  const row = parseInt(digits, 10)
  if (row < 1) return null
  const col = colToNum(letters)
  return { col, row }
}

export function formatAddress({ col, row }) {
  return numToCol(col) + String(row)
}

export function addressKey({ col, row }) {
  return col + '/' + row
}
"}

