{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-47XClT/src/tokenizer.js","content":"// Tokenizer for formula bodies.

const OPERATORS = ['<=', '>=', '<>', '^', '*', '/', '+', '-', '=', '<', '>']

export class TokenizeError extends Error {}

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    // number: digits, optional . digits, no sign, no exponent
    if (/[0-9]/.test(ch)) {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      tokens.push({ type: 'NUMBER', value: parseFloat(m[0]) })
      i += m[0].length
      continue
    }
    // identifier: letters, optionally followed by digits
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(src.slice(i))
      tokens.push({ type: 'IDENT', value: m[0].toUpperCase() })
      i += m[0].length
      continue
    }
    // operators, longest match first
    let matched = false
    for (const op of OPERATORS) {
      if (src.startsWith(op, i)) {
        tokens.push({ type: 'OP', value: op })
        i += op.length
        matched = true
        break
      }
    }
    if (matched) continue
    throw new TokenizeError('unexpected character')
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

