{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-47XClT/src/parser.js","content":"// Recursive-descent parser for formula bodies.
import { tokenize, TokenizeError } from './tokenizer.js'

export class ParseError extends Error {}

const KEYWORDS = new Set(['TRUE', 'FALSE'])
const FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expectOp(op) {
    const t = this.peek()
    if (t.type === 'OP' && t.value === op) {
      this.next()
      return true
    }
    return false
  }

  parseProgram() {
    const expr = this.parseComparison()
    if (this.peek().type !== 'EOF') {
      throw new ParseError('trailing tokens')
    }
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    for (;;) {
      const t = this.peek()
      if (t.type === 'OP' && ['=', '<>', '<', '<=', '>', '>='].includes(t.value)) {
        this.next()
        const right = this.parseAdditive()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    for (;;) {
      const t = this.peek()
      if (t.type === 'OP' && (t.value === '+' || t.value === '-')) {
        this.next()
        const right = this.parseMultiplicative()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    for (;;) {
      const t = this.peek()
      if (t.type === 'OP' && (t.value === '*' || t.value === '/')) {
        this.next()
        const right = this.parsePower()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    const t = this.peek()
    if (t.type === 'OP' && t.value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t.type === 'OP' && (t.value === '-' || t.value === '+')) {
      this.next()
      const operand = this.parseUnary()
      return { type: 'unary', op: t.value, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'number', value: t.value }
    }
    if (t.type === 'OP' && t.value === '-') {
      // handled by unary but guard anyway
    }
    if (t.type === 'LPAREN') {
      this.next()
      const expr = this.parseComparison()
      if (this.peek().type !== 'RPAREN') throw new ParseError('expected )')
      this.next()
      return expr
    }
    if (t.type === 'IDENT') {
      const name = t.value
      if (KEYWORDS.has(name)) {
        this.next()
        return { type: 'bool', value: name === 'TRUE' }
      }
      // lookahead for function call
      if (this.peek(1).type === 'LPAREN') {
        this.next() // ident
        this.next() // lparen
        const args = []
        if (this.peek().type !== 'RPAREN') {
          args.push(this.parseArgument())
          while (this.peek().type === 'COMMA') {
            this.next()
            args.push(this.parseArgument())
          }
        }
        if (this.peek().type !== 'RPAREN') throw new ParseError('expected )')
        this.next()
        return { type: 'call', name, args }
      }
      this.next()
      return { type: 'address', word: name }
    }
    throw new ParseError('unexpected token')
  }

  // Only used directly as a function argument: may be a range.
  parseArgument() {
    const t = this.peek()
    if (t.type === 'IDENT' && !KEYWORDS.has(t.value) && this.peek(1).type === 'COLON' &&
        this.peek(2).type === 'IDENT') {
      const a = t.value
      const b = this.peek(2).value
      this.next()
      this.next()
      this.next()
      return { type: 'range', from: a, to: b }
    }
    return this.parseComparison()
  }
}

// Returns the AST, or null if the grammar rejects the input.
export function parseFormula(src) {
  let tokens
  try {
    tokens = tokenize(src)
  } catch (e) {
    if (e instanceof TokenizeError) return null
    throw e
  }
  const parser = new Parser(tokens)
  try {
    return parser.parseProgram()
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}

export { FUNCTIONS }
"}

