export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function num(v) {
  return { t: 'num', v }
}
export function text(v) {
  return { t: 'text', v }
}
export function bool(v) {
  return { t: 'bool', v }
}
export function err(code) {
  return { t: 'err', v: code }
}

export function isError(value) {
  return value.t === 'err'
}

// Coerce a value to a number for an "arithmetic position".
// Returns either a number-valued result or an error result.
export function toNumber(value) {
  if (value.t === 'num') return value
  if (value.t === 'bool') return num(value.v ? 1 : 0)
  if (value.t === 'text') return err('#VALUE!')
  return value // already an error
}

export function toBool(value) {
  if (value.t === 'bool') return value
  if (value.t === 'num') return bool(value.v !== 0)
  if (value.t === 'text') return err('#VALUE!')
  return value
}

function rank(value) {
  if (value.t === 'num') return 0
  if (value.t === 'text') return 1
  return 2 // bool
}

// Compares two non-error values per the cross-kind comparison rules.
// Returns a negative number, zero, or a positive number.
export function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.t === 'num') return a.v - b.v
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  // bool: false below true
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}
"}

