export function roundSignificant(x, digits = 10) {
  if (x === 0) return 0
  return Number(x.toPrecision(digits))
}

export function formatValue(value) {
  switch (value.t) {
    case 'num':
      return String(roundSignificant(value.v))
    case 'text':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'err':
      return value.v
    default:
      throw new Error('unknown value type')
  }
}
"}

