{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-47XClT/src/sheet.js","content":"// Sheet parsing: splits stdin text into a map of declared cells.
import { parseAddress, addressKey } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

// Returns a Map keyed by "col/row" to { col, row, content, line }.
export function parseSheet(text) {
  let body = text
  if (body.endsWith('\n')) body = body.slice(0, -1)
  const lines = body === '' ? [] : body.split('\n')

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    const wsMatch = /[ \t]/.exec(stripped)
    let addressToken, content
    if (wsMatch === null) {
      addressToken = stripped
      content = ''
    } else {
      addressToken = stripped.slice(0, wsMatch.index)
      const rest = stripped.slice(wsMatch.index)
      const runMatch = /^[ \t]+/.exec(rest)
      content = rest.slice(runMatch[0].length)
    }

    const upperToken = addressToken.toUpperCase()
    const addr = parseAddress(addressToken)
    if (addr === null) {
      throw new SheetError(lineNo, `invalid cell address ${upperToken}`)
    }
    const key = addressKey(addr)
    if (cells.has(key)) {
      const canonical = require_formatAddress(addr)
      throw new SheetError(lineNo, `cell ${canonical} is declared twice`)
    }
    cells.set(key, { col: addr.col, row: addr.row, content, line: lineNo })
  }

  return cells
}

// small local helper to avoid a circular import concern; mirrors
// address.formatAddress but kept private to this module's error path.
import { formatAddress } from './address.js'
function require_formatAddress(addr) {
  return formatAddress(addr)
}
"}

