{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-47XClT/src/evaluator.js","content":"// Evaluates a parsed sheet: cell values and cell dependencies.
import { parseAddress, addressKey } from './address.js'
import { parseFormula } from './parser.js'
import { parseLiteral } from './literal.js'
import { num, bool, err, isError, toNumber, toBool, compareValues } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const MULTI_FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

function finiteOrDivZero(x) {
  if (!Number.isFinite(x)) return err('#DIV/0!')
  return num(x)
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.asts = new Map()
    this.cache = new Map()
  }

  getAst(key, cellData) {
    if (this.asts.has(key)) return this.asts.get(key)
    let ast = null
    if (cellData.content.startsWith('=')) {
      ast = parseFormula(cellData.content.slice(1))
    }
    this.asts.set(key, ast)
    return ast
  }

  evalAddress(addr) {
    const key = addressKey(addr)
    if (!this.cells.has(key)) return num(0)
    return this.evalKey(key)
  }

  evalKey(key) {
    const cached = this.cache.get(key)
    if (cached === 'computing') return err('#CYCLE!')
    if (cached !== undefined) return cached
    this.cache.set(key, 'computing')
    const cellData = this.cells.get(key)
    let result
    if (cellData.content.startsWith('=')) {
      const ast = this.getAst(key, cellData)
      result = ast === null ? err('#ERR!') : this.evalNode(ast)
    } else {
      result = parseLiteral(cellData.content)
    }
    this.cache.set(key, result)
    return result
  }

  evalNode(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'address': {
        const addr = parseAddress(node.word)
        if (addr === null) return err('#REF!')
        return this.evalAddress(addr)
      }
      case 'unary': {
        const v = this.evalNode(node.operand)
        if (isError(v)) return v
        const nv = toNumber(v)
        if (isError(nv)) return nv
        const result = node.op === '-' ? -nv.v : nv.v
        return finiteOrDivZero(result)
      }
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      case 'range':
        return err('#ERR!')
      default:
        throw new Error('unknown node type: ' + node.type)
    }
  }

  evalBinop(node) {
    const l = this.evalNode(node.left)
    const r = this.evalNode(node.right)
    if (isError(l)) return l
    if (isError(r)) return r
    const op = node.op
    if (COMPARISON_OPS.has(op)) {
      const c = compareValues(l, r)
      switch (op) {
        case '=':
          return bool(c === 0)
        case '<>':
          return bool(c !== 0)
        case '<':
          return bool(c < 0)
        case '<=':
          return bool(c <= 0)
        case '>':
          return bool(c > 0)
        case '>=':
          return bool(c >= 0)
      }
    }
    const ln = toNumber(l)
    if (isError(ln)) return ln
    const rn = toNumber(r)
    if (isError(rn)) return rn
    let result
    switch (op) {
      case '+':
        result = ln.v + rn.v
        break
      case '-':
        result = ln.v - rn.v
        break
      case '*':
        result = ln.v * rn.v
        break
      case '/':
        if (rn.v === 0) return err('#DIV/0!')
        result = ln.v / rn.v
        break
      case '^':
        result = Math.pow(ln.v, rn.v)
        break
    }
    return finiteOrDivZero(result)
  }

  rangeCells(node) {
    const a = parseAddress(node.from)
    const b = parseAddress(node.to)
    if (a === null || b === null) return null
    const minCol = Math.min(a.col, b.col)
    const maxCol = Math.max(a.col, b.col)
    const minRow = Math.min(a.row, b.row)
    const maxRow = Math.max(a.row, b.row)
    const out = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) out.push({ col: c, row: r })
    }
    return out
  }

  // Expands one function argument into the flat, ordered list of values it
  // contributes (ranges expanded to every covered cell).
  expandArg(arg, out) {
    if (arg.type === 'range') {
      const cells = this.rangeCells(arg)
      if (cells === null) {
        out.push(err('#REF!'))
        return
      }
      for (const addr of cells) out.push(this.evalAddress(addr))
      return
    }
    out.push(this.evalNode(arg))
  }

  // Evaluates a single-value argument position (ABS's operand, IF's
  // condition): a range contributes its first (top-left) cell, but any
  // error among its cells still wins.
  evalArgSingle(arg) {
    if (arg.type === 'range') {
      const cells = this.rangeCells(arg)
      if (cells === null) return err('#REF!')
      let first = null
      for (const addr of cells) {
        const v = this.evalAddress(addr)
        if (isError(v)) return v
        if (first === null) first = v
      }
      return first === null ? num(0) : first
    }
    return this.evalNode(arg)
  }

  evalCall(node) {
    const name = node.name

    if (name === 'IF') {
      if (node.args.length !== 3) return err('#ERR!')
      const condRaw = this.evalArgSingle(node.args[0])
      if (isError(condRaw)) return condRaw
      const condBool = toBool(condRaw)
      if (isError(condBool)) return condBool
      return condBool.v ? this.evalArgSingle(node.args[1]) : this.evalArgSingle(node.args[2])
    }

    if (name === 'ABS') {
      if (node.args.length !== 1) return err('#ERR!')
      const v = this.evalArgSingle(node.args[0])
      if (isError(v)) return v
      const nv = toNumber(v)
      if (isError(nv)) return nv
      return finiteOrDivZero(Math.abs(nv.v))
    }

    if (MULTI_FUNCS.has(name)) {
      if (node.args.length < 1) return err('#ERR!')
      const values = []
      for (const arg of node.args) this.expandArg(arg, values)
      for (const v of values) {
        if (isError(v)) return v
      }
      if (name === 'COUNT') {
        return num(values.filter((v) => v.t === 'num').length)
      }
      const nums = []
      for (const v of values) {
        const nv = toNumber(v)
        if (isError(nv)) return nv
        nums.push(nv.v)
      }
      if (name === 'SUM') return finiteOrDivZero(nums.reduce((a, b) => a + b, 0))
      if (name === 'MIN') return finiteOrDivZero(Math.min(...nums))
      if (name === 'MAX') return finiteOrDivZero(Math.max(...nums))
      if (name === 'AVG') return finiteOrDivZero(nums.reduce((a, b) => a + b, 0) / nums.length)
    }

    return err('#NAME?')
  }
}

// Collects every distinct address a formula AST names directly, ranges
// expanded, regardless of which branches evaluation would actually take.
export function collectDeps(node, set) {
  switch (node.type) {
    case 'number':
    case 'bool':
      return
    case 'address': {
      const addr = parseAddress(node.word)
      if (addr !== null) set.set(addressKey(addr), addr)
      return
    }
    case 'range': {
      const a = parseAddress(node.from)
      const b = parseAddress(node.to)
      if (a === null || b === null) return
      const minCol = Math.min(a.col, b.col)
      const maxCol = Math.max(a.col, b.col)
      const minRow = Math.min(a.row, b.row)
      const maxRow = Math.max(a.row, b.row)
      for (let c = minCol; c <= maxCol; c++) {
        for (let r = minRow; r <= maxRow; r++) {
          const addr = { col: c, row: r }
          set.set(addressKey(addr), addr)
        }
      }
      return
    }
    case 'unary':
      collectDeps(node.operand, set)
      return
    case 'binop':
      collectDeps(node.left, set)
      collectDeps(node.right, set)
      return
    case 'call':
      for (const arg of node.args) collectDeps(arg, set)
      return
    default:
      throw new Error('unknown node type: ' + node.type)
  }
}
