    const a = cells.get(ka)
    const b = cells.get(kb)
    if (a.col !== b.col) return a.col - b.col
    return a.row - b.row
  })

  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const key of sortedKeys) {
      const cellData = cells.get(key)
      const value = evaluator.evalKey(key)
      out.push(`${formatAddress(cellData)}=${formatValue(value)}`)
    }
  } else {
    for (const key of sortedKeys) {
      const cellData = cells.get(key)
      let names = []
      if (cellData.content.startsWith('=')) {
        const ast = parseFormula(cellData.content.slice(1))
        if (ast !== null) {
          const set = new Map()
          collectDeps(ast, set)
          names = [...set.values()].sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
        }
      }
      const suffix = names.map((a) => ' ' + formatAddress(a)).join('')
      out.push(`${formatAddress(cellData)}:${suffix}`)
    }
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
